FILL=[" uh"," um"," like"," you know"," basically"," sort of"," kind of"," erm"," I mean"," just"]
def genk(k,seed,seen):
    r=random.Random(seed); out=[]; lab=[]
    FR={c:[f for i,f in enumerate(F[c]) if i%10==k or i%10==(k+5)%10 and False] or [F[c][k]] for c in CATS}
    # frames: those with index%10==k (two per category in 20-frame lists)
    PR=[p for i,p in enumerate(PRE) if i%3==k%3 or p==""]
    IN=[p for i,p in enumerate(IND) if i%2==k%2 or p==""]
    SU=[p for i,p in enumerate(SUF) if i%3==(k//3)%3 or p==""]
    while len(out)<N:
        c=r.choices(CATS,W)[0]; t=r.choice(FR[c])
        m=fill(r,t)
        if r.random()<.35 and re.match(r"(put|add|set|turn|open|remind|text|call|ring|send|email|write|make|delete|show|find|play|start|log|mark|tick|save|snooze|push|park|hold|delay|get|jot|stick|chuck|pop|cancel|scrap|bin|drop|remove|clear|take|plan|build|give|tell|list|read|copy|search|google|look|switch|bring|launch|fire|load|pull|wake|alarm|timer|count|time|convert|calculate|work|forget|remember|record|note|track|check|update|change|move|rename|edit|break|split|apply|use|run|stamp|insert|load|create|draft|compose|shoot|dial|phone|buzz|contact|connect|go|be|speak|talk|try|reply|respond|adopt|help|let|text|ping|notify|nudge|alert|prompt|block|book|schedule|organise|sort|lay|map|walk|brief|analyse|reflect|review|dispatch|mail|fix|reprioritise|adjust|tweak|bump|expand|detail|divide|scan|extract|quote|consult|hunt|dig|crunch|solve|compute|figure|do|express|view|stop|end|begin|lose|strike|dump|wipe|purge|erase|un-remember|stop)\b",m): m=r.choice(IN)+m
        if r.random()<.3 and " " in m:
            w=m.split(" "); j=r.randrange(1,len(w)); w.insert(j,r.choice(FILL).strip()); m=" ".join(w)
        m=r.choice(PR)+m+r.choice(SU)
        m=m.strip()
        x=r.random()
        if x<.18: m=re.sub(r"[,.!?]","",m).lower()
        elif x<.5: m=m[0].upper()+m[1:]
        if r.random()<.04 and len(m)>6:
            i=r.randrange(1,len(m)-2); m=m[:i]+m[i+1]+m[i]+m[i+2:]
        h=hash(m)
        if h in seen: continue
        seen.add(h); out.append(m); lab.append(CATS.index(c))
    return out,lab
if __name__=="__main__":
    k=int(sys.argv[1]); seen=set()
    for n in range(101+10*k,111+10*k):
        d,l=genk(k,90000+n,seen)
        with open(f"{HERE}jarvis_messages_{n}.md","w") as f:
            f.write(f"# Jarvis Real-Speech Messages, Set {n}\n\n1,000,000 messages, speech round {k+1}. Labels in .labels sidecar.\n\n")
            f.writelines(f"{i}. {m}\n" for i,m in enumerate(d,1))
        open(f"{HERE}jarvis_messages_{n}.labels","w").write("\n".join(map(str,l))+"\n")
        print(n,flush=True)
